// Decide is the compiled decision list. Earlier cases take precedence,
// exactly as the chips were mined and approved.
func Decide(obs game.Sight) (msg.Move, bool) {
	switch {
	case pred.PreferredCellIs(obs, 4):
		// chip preferred_cell_is_4 → play_4 (coverage 800, counterexamples 0)
		return msg.Move{Cell: 4}, true
	case pred.PreferredCellIs(obs, 0):
		// chip preferred_cell_is_0 → play_0 (coverage 706, counterexamples 0)
		return msg.Move{Cell: 0}, true
	case pred.WinningMoveIs(obs, 8):
		// chip winning_move_is_8 → play_8 (coverage 516, counterexamples 0)
		return msg.Move{Cell: 8}, true
	case pred.WinningMoveIs(obs, 6):
		// chip winning_move_is_6 → play_6 (coverage 122, counterexamples 0)
		return msg.Move{Cell: 6}, true
	case pred.WinningMoveIs(obs, 1):
		// chip winning_move_is_1 → play_1 (coverage 78, counterexamples 0)
		return msg.Move{Cell: 1}, true
	case pred.WinningMoveIs(obs, 3):
		// chip winning_move_is_3 → play_3 (coverage 46, counterexamples 0)
		return msg.Move{Cell: 3}, true
	case pred.BlockingMoveIs(obs, 2):
		// chip blocking_move_is_2 → play_2 (coverage 38, counterexamples 0)
		return msg.Move{Cell: 2}, true
	case pred.BlockingMoveIs(obs, 5):
		// chip blocking_move_is_5 → play_5 (coverage 30, counterexamples 0)
		return msg.Move{Cell: 5}, true
	case pred.BlockingMoveIs(obs, 6):
		// chip blocking_move_is_6 → play_6 (coverage 20, counterexamples 0)
		return msg.Move{Cell: 6}, true
	case pred.BlockingMoveIs(obs, 3):
		// chip blocking_move_is_3 → play_3 (coverage 16, counterexamples 0)
		return msg.Move{Cell: 3}, true
	case pred.WinningMoveIs(obs, 5):
		// chip winning_move_is_5 → play_5 (coverage 12, counterexamples 0)
		return msg.Move{Cell: 5}, true
	case pred.BlockingMoveIs(obs, 7):
		// chip blocking_move_is_7 → play_7 (coverage 40, counterexamples 0)
		return msg.Move{Cell: 7}, true
	case pred.PreferredCellIs(obs, 2):
		// chip preferred_cell_is_2 → play_2 (coverage 174, counterexamples 0)
		return msg.Move{Cell: 2}, true
	case pred.PreferredCellIs(obs, 3):
		// chip preferred_cell_is_3 → play_3 (coverage 12, counterexamples 0)
		return msg.Move{Cell: 3}, true
	case pred.PreferredCellIs(obs, 5):
		// chip preferred_cell_is_5 → play_5 (coverage 6, counterexamples 0)
		return msg.Move{Cell: 5}, true
	case pred.PreferredCellIs(obs, 1):
		// chip preferred_cell_is_1 → play_1 (coverage 4, counterexamples 0)
		return msg.Move{Cell: 1}, true
	case pred.PreferredCellIs(obs, 6):
		// chip preferred_cell_is_6 → play_6 (coverage 4, counterexamples 0)
		return msg.Move{Cell: 6}, true
	case pred.PreferredCellIs(obs, 7):
		// chip preferred_cell_is_7 → play_7 (coverage 4, counterexamples 0)
		return msg.Move{Cell: 7}, true
	case pred.PreferredCellIs(obs, 8):
		// chip preferred_cell_is_8 → play_8 (coverage 4, counterexamples 0)
		return msg.Move{Cell: 8}, true
	}
	var zero msg.Move
	return zero, false
}

// Distilled seats the compiled policy behind api:agent-interface: an
// ordinary agent, indistinguishable from a hand-written bot.
type Distilled struct {
	last game.Sight
	has  bool
}

func (*Distilled) Joined(session.SlotID) {}

func (a *Distilled) Observe(obs game.Sight) { a.last, a.has = obs, true }

func (a *Distilled) Decide(context.Context) (msg.Move, bool) {
	if !a.has {
		var zero msg.Move
		return zero, false
	}
	return Decide(a.last)
}

func (*Distilled) Ended(session.Result) {}

// actionName maps a decided action back to its vocabulary term, for
// the generated episode-fixture tests.
func actionName(a msg.Move) string {
	switch a {
	case msg.Move{Cell: 0}:
		return "play_0"
	case msg.Move{Cell: 1}:
		return "play_1"
	case msg.Move{Cell: 2}:
		return "play_2"
	case msg.Move{Cell: 3}:
		return "play_3"
	case msg.Move{Cell: 4}:
		return "play_4"
	case msg.Move{Cell: 5}:
		return "play_5"
	case msg.Move{Cell: 6}:
		return "play_6"
	case msg.Move{Cell: 7}:
		return "play_7"
	case msg.Move{Cell: 8}:
		return "play_8"
	}
	return ""
}
